<template><section class="space-y-5"><div class="flex justify-between"><h1 class="text-2xl font-bold text-white">广告活动</h1><NuxtLink :to="localized('/supplier/ads/create')" class="btn-primary">创建广告</NuxtLink></div><div v-for="item in items" :key="item.id" class="pc-card flex justify-between gap-4"><div><p class="font-semibold text-white">{{ item.title }}</p><p class="text-sm text-slate-400">{{ item.status }} · {{ item.clicks }} clicks · {{ item.impressions }} impressions</p></div><button v-if="item.status==='DRAFT'||item.status==='ACTIVE'" class="text-primary-300" @click="toggle(item)">{{ item.status==='ACTIVE'?'Pause':'Submit' }}</button></div><p v-if="error" class="text-red-300">{{ error }}</p></section></template>


<script setup lang="ts">const { localized } = useLocalizedLink(); definePageMeta({layout:'procurement',middleware:['auth']});const {apiFetch}=useApi();const items=ref<any[]>([]);const error=ref('');async function load(){items.value=(await apiFetch<any>('/cebu-trade/ads/campaigns')).items}async function toggle(x:any){await apiFetch(`/cebu-trade/ads/campaigns/${x.id}/status`,{method:'PATCH',body:{status:x.status==='ACTIVE'?'PAUSED':'PENDING_REVIEW'}});await load()}onMounted(()=>load().catch((e:any)=>error.value=e?.data?.detail||e?.message))</script>
